def max_pyramid_height(n):
    left, right = 0, n
    while left <= right:
        mid = (left + right) // 2
        cubes_needed = mid * (mid + 1) // 2
        if cubes_needed == n:
            return mid
        elif cubes_needed < n:
            left = mid + 1
        else:
            right = mid - 1
    return right

